{
  "name": "opencode-ds-peak",
  "version": "0.3.6",
  "description": "Minimal opencode TUI sidebar dot showing whether DeepSeek is in peak or off-peak pricing, with a countdown to the next switch. Five languages.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "plugin",
    "deepseek",
    "pricing",
    "peak",
    "off-peak",
    "discount",
    "cost",
    "countdown",
    "sidebar",
    "i18n"
  ],
  "license": "MIT",
  "author": "MendelDamian",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/MendelDamian/opencode-ds-peak.git"
  },
  "homepage": "https://github.com/MendelDamian/opencode-ds-peak",
  "bugs": {
    "url": "https://github.com/MendelDamian/opencode-ds-peak/issues"
  },
  "type": "module",
  "engines": {
    "node": ">=20"
  },
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "sanity": "node --experimental-strip-types scripts/sanity-check.mjs",
    "check": "npm run typecheck && npm run sanity",
    "pack": "npm pack --dry-run"
  },
  "dependencies": {
    "@opentui/core": "^0.8.0",
    "@opentui/keymap": "^0.8.0",
    "@opentui/solid": "^0.8.0",
    "solid-js": "^1.9.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.18.29",
    "@opencode/plugin": ">=2.0.22"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.34",
    "@opencode/plugin": "^2.0.22",
    "@opencode/theme": "^2.0.22",
    "@types/node": "^26.6.4",
    "typescript": "^7.0.2"
  },
  "overrides": {
    "@babel/core": "^7.29.6",
    "glob": "^14.0.2",
    "minimatch": "^11.0.1",
    "seroval": "^1.6.3",
    "toml": "^5.0.1",
    "zod": "^4.6.6"
  }
}
